// Récupère le run_id le plus récent de WF8 (advisor) et regroupe les top items WF7 du jour
const bcl = $('Lire business_control').all().map(i => i.json);
const kpis = $('Lire kpi_snapshots').all().map(i => i.json);

const sortByTsDesc = (a, b) => String(b.ts || '').localeCompare(String(a.ts || ''));

const lastAdvisor = bcl.filter(b => b.source_workflow === 'WF8').sort(sortByTsDesc)[0] || {};
const lastWF7Run  = (bcl.filter(b => b.source_workflow === 'WF7').sort(sortByTsDesc)[0] || {}).run_id || '';
const topItems = bcl
  .filter(b => b.source_workflow === 'WF7' && b.run_id === lastWF7Run)
  .slice(0, 10)
  .map(b => ({
    item_type: b.item_type,
    item_id: b.item_id,
    title: b.title,
    priority_level: b.priority_level,
    recommended_action: b.recommended_action,
    assigned_to: b.assigned_to,
    recommendation: b.recommendation
  }));

const lastKpi = kpis.sort(sortByTsDesc)[0] || {};
let advisorPayload = {};
try {
  advisorPayload = lastAdvisor.notes ? JSON.parse(lastAdvisor.notes) : {};
} catch (e) { advisorPayload = {}; }

const week_label = lastKpi.period || (() => {
  const d = new Date();
  const oj = new Date(d.getFullYear(), 0, 1);
  const w = Math.ceil((((d - oj) / 86400000) + oj.getDay() + 1) / 7);
  return `${d.getFullYear()}-W${String(w).padStart(2, '0')}`;
})();

return [{
  json: {
    week_label,
    top_items: topItems,
    advisor: {
      weekly_priorities: (lastAdvisor.recommendation || '').split(' | ').filter(Boolean),
      ...advisorPayload
    },
    kpis: lastKpi
  }
}];

