// Parse digest et prépare draft Gmail interne
const llm = $json;
let d = {};
try {
  const c = llm && llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
  if (c) d = JSON.parse(c);
} catch (e) { d = { _llm_error: String(e && e.message || e) }; }

return [{
  json: {
    subject: d.subject || 'Symbalyx — Synthèse hebdo',
    digest_markdown: d.digest_markdown || (d._llm_error ? ('Erreur LLM: ' + d._llm_error) : ''),
    decisions_to_validate: d.decisions_to_validate || [],
    to_email: $env && $env.INTERNAL_DIGEST_TO ? $env.INTERNAL_DIGEST_TO : 'arsene+kentin@symbalyx.local'
  }
}];
